<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { Coin, CreditCard, Refresh } from '@element-plus/icons-vue';
import { apiRequest } from '../../lib/api.js';
const cardKey=ref(''),requestId=ref(''),requestKey=ref(''),kind=ref('formal'),notice=ref(''),error=ref(''),loading=ref(false),redeeming=ref(false),data=ref({balance:{formal:0,test:0,updated:0},ledger:[]});
const ledger=computed(()=>data.value.ledger.filter(row=>row.kind===kind.value));
async function load(){loading.value=true;error.value='';try{data.value=await apiRequest('points')}catch(cause){error.value=cause.message}finally{loading.value=false}}
function newRequestId(){return globalThis.crypto?.randomUUID?.()||`redeem-${Date.now()}-${Math.random().toString(36).slice(2)}`}
async function redeem(){const key=cardKey.value.trim();if(!key){error.value='请输入积分卡 Key。';return}if(requestKey.value!==key){requestKey.value=key;requestId.value=newRequestId()}redeeming.value=true;error.value='';try{const result=await apiRequest('points/redeem',{method:'POST',body:{key,requestId:requestId.value}});cardKey.value='';requestKey.value='';requestId.value='';await load();window.dispatchEvent(new Event('douyinjuhe-billing'));notice.value=`兑换成功，到账 ${result.amount} ${result.kind==='formal'?'正式':'测试'}积分${result.replay?'（已恢复上次提交结果）':''}。`}catch(cause){error.value=cause.message}finally{redeeming.value=false}}
const time=value=>value?new Date(value).toLocaleString():'-';
onMounted(()=>{window.addEventListener('douyinjuhe-session',load);load()});onUnmounted(()=>window.removeEventListener('douyinjuhe-session',load));
</script>
<template><section class="points-page" aria-label="积分兑换"><div class="summary-grid"><article class="balance-card formal"><div class="card-title"><span><el-icon><Coin/></el-icon></span><div><strong>正式积分</strong><small>生产环境可用积分</small></div></div><b>{{data.balance.formal}}</b><footer>更新于 {{time(data.balance.updated)}} <el-button text :icon="Refresh" :loading="loading" aria-label="刷新正式积分" @click="load"/></footer></article><article class="balance-card test"><div class="card-title"><span><el-icon><Coin/></el-icon></span><div><strong>测试积分</strong><small>测试环境可用积分</small></div></div><b>{{data.balance.test}}</b><footer>更新于 {{time(data.balance.updated)}} <el-button text :icon="Refresh" :loading="loading" aria-label="刷新测试积分" @click="load"/></footer></article><article class="redeem-card"><div class="card-title"><span><el-icon><CreditCard/></el-icon></span><strong>兑换积分卡</strong></div><p>输入管理员发放的积分卡 Key，兑换后自动进入对应积分类型。</p><div class="redeem-row"><el-input v-model="cardKey" placeholder="HZ-FORMAL-..." @keyup.enter="redeem"/><el-button type="primary" :loading="redeeming" @click="redeem">立即兑换</el-button></div></article></div><el-alert v-if="notice" :title="notice" type="success" show-icon @close="notice=''"/><el-alert v-if="error" :title="error" type="error" show-icon @close="error=''"/><section class="ledger"><div class="ledger-heading"><div><h2>积分流水</h2><small>共 {{ledger.length}} 条</small></div><el-radio-group v-model="kind" size="small"><el-radio-button value="formal">正式积分</el-radio-button><el-radio-button value="test">测试积分</el-radio-button></el-radio-group></div><el-table v-loading="loading" :data="ledger" empty-text="暂无积分流水"><el-table-column label="时间" width="180"><template #default="{row}">{{time(row.created)}}</template></el-table-column><el-table-column label="类型" width="100"><template #default="{row}">{{row.kind==='formal'?'正式积分':'测试积分'}}</template></el-table-column><el-table-column label="变动" width="100"><template #default="{row}"><span :class="row.delta>0?'positive':'negative'">{{row.delta>0?'+':''}}{{row.delta}}</span></template></el-table-column><el-table-column prop="balance" label="余额" width="100"/><el-table-column prop="reason" label="说明" min-width="180"/></el-table></section></section></template>
<style scoped>.points-page{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;min-width:0}.summary-grid{display:grid;grid-template-columns:1fr 1fr 1.35fr;gap:18px;min-width:0}.balance-card,.redeem-card,.purchase,.ledger{background:#fff;border-radius:18px;box-shadow:0 4px 12px #35497905;min-width:0}.balance-card,.redeem-card,.purchase{min-height:216px;padding:24px}.card-title{display:flex;align-items:center;gap:12px}.card-title>span{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:#fff1d9;color:#c78b19;font-size:19px}.test .card-title>span{background:#eaf0ff;color:#2d65f2}.redeem-card .card-title>span{background:#e3f5eb;color:#18a05d}.card-title strong{display:block;font-size:17px}.card-title small,.redeem-card p,.balance-card footer,.ledger-heading small{display:block;color:#8b99ae;font-size:12px}.balance-card b{display:block;font-size:34px;line-height:1.1;margin-top:34px;color:#172442;font-weight:650}.balance-card footer{display:flex;align-items:center;justify-content:space-between;margin-top:24px}.redeem-card p{margin:22px 0 50px}.redeem-row{display:grid;grid-template-columns:minmax(0,1fr) 120px;gap:12px}.ledger{padding:24px;min-height:280px;overflow:hidden}.purchase{padding:24px}.ledger-heading{display:flex;justify-content:space-between;align-items:start;margin-bottom:20px}.ledger-heading h2{font-size:18px;margin:0 0 5px}.ledger :deep(.el-table__empty-block){min-height:180px}.product-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.product{border:1px solid #e2e8f3;background:#fbfcff;border-radius:10px;text-align:left;padding:16px;display:grid;gap:8px;color:#3d4d68}.product.selected{border-color:#4d7ff3;box-shadow:0 0 0 2px #4d7ff322;background:#f4f7ff}.product b{font-size:20px;color:#1d5fe8}.product small{color:#8997ab}.purchase-actions{display:flex;gap:10px;margin-top:16px}.positive{color:#15945b}.negative{color:#d84d4d}@media(max-width:1000px){.summary-grid{grid-template-columns:1fr 1fr}.redeem-card{grid-column:1/-1}}@media(max-width:650px){.summary-grid{grid-template-columns:minmax(0,1fr)}.redeem-card{grid-column:auto}.balance-card,.redeem-card,.purchase,.ledger{padding:16px}.redeem-card p{margin-bottom:22px}.redeem-row,.purchase-actions{grid-template-columns:minmax(0,1fr);display:grid}.ledger-heading{gap:12px;flex-wrap:wrap}}</style>
